def count_divisors(n):
    """Return True if the number of positive divisors of n is even, else False.

    A positive integer has an odd number of positive divisors exactly when it
    is a perfect square; otherwise the divisor count is even.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count % 2 == 0

